    public void service(@Val String idempotencyKey, @Val Owner owner, IdempotencyStore idempotencyStore) {
        if (idempotencyKey != null && owner.getId() != null) {
            idempotencyStore.putIfAbsent(idempotencyKey, owner.getId());
        }
    }
}

